mapper.select:
select dev.`id` as `deviceId`, dev.`device_parent_id` as `deviceParentId`, dev.`device_number` as `deviceNumber`, dev.`name` as `deviceName`, dev.`product_id` as `productId`, prod.`prod_name` as `productName`, prod.`prod_model` as `prodModel`, prod.`prod_brand_id` as `prodBrandId`, (select `item_value` from `iot_sys_dict_item` item where item.`id` = prod.`prod_brand_id`) as `prodBrandCode`, (select `item_label` from `iot_sys_dict_item` item where item.`id` = prod.`prod_brand_id`) as `prodBrandName`, prod.`prod_category_id` as `prodCategoryId`, (select `item_value` from `iot_sys_dict_item` item where item.`id` = prod.`prod_category_id`) as `prodCategoryCode`, (select `item_label` from `iot_sys_dict_item` item where item.`id` = prod.`prod_category_id`) as `prodCategoryName`, temp.`item_label_concat` as `prodCategoryNameConcat`,
LISTAGG(tag.`tag_name`) as `tags`
GROUP_CONCAT(tag.`tag_name`) as `tags`
from `iot_dev_device` dev join `iot_md_product` prod on dev.`product_id` = prod.`id` left join `iot_sys_dict_temp_table` temp on prod.`prod_category_id` = temp.`id` LEFT JOIN `center_biz_tag_ref` tr on tr.`business_key` = dev.`id` and tr.`deleted` = 0 LEFT JOIN `center_biz_tag` tag on tag.`id` = tr.`tag_id` and tag.`deleted` = 0 and tag.`tag_code` like 'custom.app::deviceCenter%' where 1 = 1
and dev.`product_id` = #{productId}
and dev.`device_number` like concat('%', #{deviceQueryParam.deviceCode}, '%')
and prod.`prod_category_id` = #{deviceQueryParam.prodCategoryCode}
and prod.`prod_brand_id` = #{deviceQueryParam.prodBrandCode}
and dev.`name` like concat('%', #{deviceQueryParam.deviceNameLike}, '%')
GROUP BY dev.`id`

select dev.`product_id`
from `iot_dev_device` dev
where dev.`id` = #{deviceId}
